\label{lem:finite-factorization}
Let $R$ be a commutative integral domain with quotient field $K$.
\begin{enumerate}
\item Every homomorphism from a finitely generated $R$-module to a flat
$R$-module factors through a finitely generated free module.
\item If $N$ is a finitely generated Gorenstein flat $R$-module, then
$\operatorname{Ext}_R^1(N,F)=0$ for every flat $R$-module $F$.
\end{enumerate}

\label{lem:qcs-normal}
Let $R$ be an integrally closed domain. If every overring of $R$ is
Gorenstein flat as an $R$-module, then $R$ is Pr\"ufer.

\label{lem:qcs-seminormal-conductor}
Let $D$ be a seminormal domain and $U$ an overring.  Then the conductor
$(D:U)$ is a radical ideal of $U$, and hence of $D$.

\label{lem:quotient-degree-one}
Let $R$ be a domain and let $T=R+Rx\subseteq\operatorname{Frac} R$ be a proper
overring that is Gorenstein flat over $R$. Put $C=(R:T)$ and $A=R/C$.
For every $A$-module $L$ there are natural isomorphisms
\begin{equation}\label{eq:qcs-ext-shift}
 \operatorname{Ext}_R^{i+1}(L,R)\cong\operatorname{Ext}_A^i(L,A)\quad(i\ge0),
 \qquad \operatorname{Hom}_R(L,R)=0.
\end{equation}
The degree-one isomorphism sends $\phi:L\to A$ to the pullback of
$0\to R\to T\to A\to0$, where $T\to A$ sends $r+sx$ to $s+C$.

\label{prop:cp-finite-patching}
Let $R$ be a commutative ring, let $I$ be an ideal, and put $B=R/I$.
Suppose that $f_1,\ldots,f_r\in R$ and finitely generated ideals
$C_1,\ldots,C_s$ satisfy the following conditions:
\begin{enumerate}
\item $B_{f_i}\in\mathcal D_1(R)$ for every $i$;
\item every $R/C_j$-module belongs to $\mathcal D_1(R)$ for every $j$;
\item the prime ideals containing $I$ are covered as follows:
\[
 V(I)\subseteq\bigcup_{i=1}^r D(f_i)\ \cup\
                 \bigcup_{j=1}^s V(C_j).
\]
\end{enumerate}
Then $B\in\mathcal D_1(R)$.  Either indexing set is allowed to be empty.

\label{prop:cp-finite-certificate}
Let $R$ be a domain satisfying $\mathrm{(O)}$, and let $I$ be a nonzero finitely
generated proper ideal.  There are finitely many elements
$f_1,\ldots,f_r$ and finitely many proper overrings
$T_j=R+Rz_j$ with conductors $C_j=(R:T_j)$ such that
\begin{enumerate}
\item $I_{f_i}=a_iR_{f_i}$ for some $0\ne a_i\in I$, for every $i$;
\item each $C_j$ is nonzero and finitely generated, and every
$R/C_j$-module has Gorenstein flat dimension at most one over $R$;
\item $V(I)\subseteq\bigcup_iD(f_i)\cup\bigcup_jV(C_j)$.
\end{enumerate}
In particular, for some $e\ge1$,
\[
 (C_1\cdots C_s)^e\subseteq I+(f_1,\ldots,f_r),
\]
using the same empty-product convention as above.

\label{thm:cp-main}
Let $R$ be a commutative integral domain with quotient field $K$.
The following conditions are equivalent:
\begin{enumerate}
\item $R$ is a Gorenstein Pr\"ufer domain;
\item every overring $R\subseteq T\subseteq K$ is Gorenstein flat as an
$R$-module;
\item $R[z_1,\ldots,z_n]$ is Gorenstein flat as an $R$-module for every
finite set $z_1,\ldots,z_n\in K$.
\end{enumerate}
In particular, the overring hypothesis forces coherence and
$\operatorname{fd}_R E\le1$ for every injective $R$-module $E$.
